import{_ as e}from"./chunks/library-overview.Bu864uIA.js";import{_ as a}from"./chunks/volume-settings.DLnHK18N.js";import{_ as d,o as s,c as o,a2 as n}from"./chunks/framework.Dx-TCpNt.js";const k=JSON.parse('{"title":"图库与导入","description":"图库在每次应用加载时扫描 raw/ 文件夹生成。没有数据库，也没有把扫描件复制一遍的导入步骤：目录结构本身就是配置。","frontmatter":{"description":"图库在每次应用加载时扫描 raw/ 文件夹生成。没有数据库，也没有把扫描件复制一遍的导入步骤：目录结构本身就是配置。"},"headers":[],"relativePath":"zh/guide/gallery.md","filePath":"zh/guide/gallery.md","lastUpdated":1794777339000}'),r={name:"zh/guide/gallery.md"};function i(l,t,c,p,h,g){return s(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="图库与导入" tabindex="-1">图库与导入 <a class="header-anchor" href="#图库与导入" aria-label="Permalink to &quot;图库与导入&quot;">​</a></h1><p>图库在每次应用加载时扫描 <code>raw/</code> 文件夹生成。没有数据库，也没有把扫描件复制一遍的导入步骤：<strong>目录结构本身就是配置</strong>。</p><p>本页介绍怎么摆文件、扫描器怎么配对语言、怎么把放在别处的文件夹挂进图库，以及几个导入入口各自通向哪里。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>漫画扫描件的文件夹结构千奇百怪：<code>Vol.14/Japanese/ch01</code>、<code>点兔第14卷/ja/172</code>、<code>manga/zh-cn/172</code>。你希望有一个书架统一列出卷和话，把每种语言的第 1 页和其他语言的第 1 页对上，缺文件时直接告诉你缺在哪——而不用先重命名或搬运任何东西。</p><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/</span></span>
<span class="line"><span>  &lt;volume&gt;/</span></span>
<span class="line"><span>    &lt;language-dir&gt;/</span></span>
<span class="line"><span>      &lt;chapter&gt;/</span></span>
<span class="line"><span>        001.jpg</span></span>
<span class="line"><span>        002.jpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li><strong>卷</strong> 是 <code>raw/</code> 下的任意一级文件夹。</li><li><strong>话</strong> 是语言目录内的任意文件夹。各语言的话会取并集，所以某个版本可以整话缺席。</li><li><strong>页面按排序位置配对，不是按文件名。</strong> 每种语言先做自然排序（连续数字按数值比较），再按索引配对。<code>1.jpg</code>、<code>2.jpg</code>、<code>10.jpg</code> 会乖乖排对。</li></ul><figure class="shot"><img src="`+e+`" alt="图库侧栏，含卷、话与语言标记"><figcaption>侧栏按 卷 → 话 → 页 列出。语言标记显示这一卷有哪几个版本；警告会就地显示。</figcaption></figure><h2 id="语言目录名" tabindex="-1">语言目录名 <a class="header-anchor" href="#语言目录名" aria-label="Permalink to &quot;语言目录名&quot;">​</a></h2><p>扫描器会先规范化文件夹名（转小写，空格和下划线换成连字符），再与别名匹配：</p><table tabindex="0"><thead><tr><th>语言</th><th>可识别的目录名</th></tr></thead><tbody><tr><td>日语（<code>ja</code>）</td><td><code>ja</code>、<code>jp</code>、<code>jpn</code>、<code>japanese</code>、<code>ja-jp</code>、<code>日</code>、<code>日本語</code>、<code>日文</code></td></tr><tr><td>中文（<code>zh</code>）</td><td><code>zh</code>、<code>zh-cn</code>、<code>zh-hans</code>、<code>zh-sg</code>、<code>cn</code>、<code>chs</code>、<code>zh-tw</code>、<code>zh-hk</code>、<code>zh-hant</code>、<code>cht</code>、<code>tw</code>、<code>hk</code>、<code>中</code>、<code>中文</code>、<code>繁中</code>、<code>简中</code></td></tr><tr><td>英语（<code>en</code>）</td><td><code>en</code>、<code>en-us</code>、<code>en-gb</code>、<code>us</code>、<code>uk</code>、<code>eng</code>、<code>english</code>、<code>英</code>、<code>英文</code></td></tr></tbody></table><p>文件夹名认不出来时，这一卷照样出现，只是挂一条警告。打开 <strong>卷设置</strong>（卷所在行的齿轮）把目录指定给某种语言。选择保存在 <code>data/library.json</code>：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;volumes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;点兔第14卷&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;dirs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>一卷能挂多少种语言，取决于你映射出多少；内置的三种只是常客。对照阅读只提供当前页实际存在的语言。</p><h2 id="卷设置" tabindex="-1">卷设置 <a class="header-anchor" href="#卷设置" aria-label="Permalink to &quot;卷设置&quot;">​</a></h2><p>卷设置是给“目录没好好自我介绍”的卷准备的修理间。点击卷所在行的齿轮打开。</p><ol><li>对话框会为这一卷识别到的每种语言各列一个下拉框，另外默认提供 <strong>日语</strong>、<strong>中文</strong> 和 <strong>英语</strong>。</li><li>为每种语言选对应的子文件夹。<strong>不使用 / 自动</strong> 表示交回给自动识别。</li><li>点击<strong>保存</strong>。图库会重新扫描，这一卷的语言标记随之更新。</li><li><strong>从图库移除</strong>只删掉 <code>raw/</code> 下的链接；原文件夹里的图片和 <code>data/pages/</code> 里的标注都还在。</li></ol><p>一个文件夹只能归一种语言；已经被占用的文件夹会从其他下拉框里消失。如果一个语言文件夹都没识别出来，对话框会直说，并把这一卷的警告原因复述一遍。</p><figure class="shot"><img src="`+a+'" alt="卷设置对话框：ja、zh、en 各有一个下拉框，底部有“从图库移除”“取消”“保存”"><figcaption>卷设置：每种语言的下拉框指向对应的子目录。保存后会重新扫描本卷；“从图库移除”只删除 raw/ 下的链接。</figcaption></figure><div class="tip custom-block"><p class="custom-block-title">先定好映射，再开始标注</p><p>分格和笔记按卷、话保存。之后修改映射，页面数据就可能找不回来。请先设好映射、打开几页确认，再动手修分格。</p></div><h2 id="添加位于其他位置的文件夹" tabindex="-1">添加位于其他位置的文件夹 <a class="header-anchor" href="#添加位于其他位置的文件夹" aria-label="Permalink to &quot;添加位于其他位置的文件夹&quot;">​</a></h2><p><strong>＋ 添加漫画</strong> 有两种模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>结果</th></tr></thead><tbody><tr><td>路径留空</td><td>在 <code>raw/</code> 下创建一个空文件夹。</td></tr><tr><td>选择已有文件夹</td><td>在 <code>raw/</code> 下创建一个指向原目录的<strong>目录链接</strong>。图片不会被复制；链接的行为与普通文件夹一致，因此标注仍可正常写入。</td></tr></tbody></table><p>可选：为这一卷指定一个不同的显示名称。输入框下方的提示会重申预期的目录结构：<code>language/chapter/page.jpg</code>。</p><p><strong>从图库移除</strong>（位于卷设置）只删除 <code>raw/</code> 下的链接；原文件夹中的图片不受影响，已经保存到 <code>data/pages/</code> 的标注也会保留。</p><p>在普通浏览器中弹不出文件夹选择框。请直接填写绝对路径，或使用桌面版并点击 <strong>选择文件夹…</strong>。</p><h2 id="页面与语言的角色" tabindex="-1">页面与语言的角色 <a class="header-anchor" href="#页面与语言的角色" aria-label="Permalink to &quot;页面与语言的角色&quot;">​</a></h2><p>有三种容易混淆的“角色”：</p><table tabindex="0"><thead><tr><th>角色</th><th>在哪里选择</th><th>影响什么</th></tr></thead><tbody><tr><td><strong>底图</strong></td><td>切格工作台工具栏</td><td>在哪种语言的画面上画分格。分格矩形由该页的所有语言共用。</td></tr><tr><td><strong>对照语言</strong></td><td>对照阅读的语言标签</td><td>显示哪些语言、以什么顺序显示。不必启用所有语言。</td></tr><tr><td><strong>首选语言</strong></td><td>PNG 导出</td><td>整页与单格 PNG 使用基准语言；三语拼图使用所选的对照语言。</td></tr></tbody></table><p>分格与笔记按页面存储一份，而不是每种语言一份。对齐偏移按语言存储，也可以按分格存储。</p><h2 id="你会看到的警告" tabindex="-1">你会看到的警告 <a class="header-anchor" href="#你会看到的警告" aria-label="Permalink to &quot;你会看到的警告&quot;">​</a></h2><p>图库警告只是碎碎念，不是报错：页面照样能开。</p><table tabindex="0"><thead><tr><th>警告</th><th>含义</th><th>处理</th></tr></thead><tbody><tr><td><em>未识别到语言目录</em></td><td>没有任何子文件夹匹配别名。</td><td>在卷设置里手工映射，或重命名。</td></tr><tr><td><em>未识别的目录：…</em></td><td>语言目录旁边还有其他文件夹。</td><td>映射它们，或直接忽略。</td></tr><tr><td><em>各语言页数不一致</em></td><td>各语言的文件数量不同。</td><td>配对按索引进行；补齐或删除缺失的那一页。</td></tr><tr><td><em>本话扩展名混用</em></td><td>例如 <code>.jpg</code> 与 <code>.png</code> 交替出现。</td><td>通常无妨；如果在意缩略图一致，可统一格式。</td></tr><tr><td><em>文件名与页序不符</em></td><td>文件名开头的数字与它的排序位置不一致。</td><td>如果这种不一致意味着缺页或多页，请重命名。</td></tr></tbody></table><h2 id="特殊目录结构" tabindex="-1">特殊目录结构 <a class="header-anchor" href="#特殊目录结构" aria-label="Permalink to &quot;特殊目录结构&quot;">​</a></h2><p>默认结构能覆盖大多数图库。如果你的目录把系列放在最前面、把语言放在最后，或者根本没有语言文件夹，打开<strong>目录识别规则…</strong>，用占位符描述路径即可。规则按顺序尝试，第一条匹配的生效；它只影响识别，不会重命名或移动文件。</p><p>完整语法、规则字段和预览流程见<a href="/KomaYomi-docs/zh/guide/folder-rules">目录识别规则</a>。</p><h2 id="导入、交换与恢复" tabindex="-1">导入、交换与恢复 <a class="header-anchor" href="#导入、交换与恢复" aria-label="Permalink to &quot;导入、交换与恢复&quot;">​</a></h2><p>侧栏里有四个不同的入口，各自负责不同的事：</p><table tabindex="0"><thead><tr><th>入口</th><th>用途</th></tr></thead><tbody><tr><td><strong>添加漫画</strong></td><td>把已有图片文件夹链接进图库。</td></tr><tr><td><strong>工程文件…</strong></td><td>导出或导入 <code>.mnproj</code> 包（图片 + 标注 + 模板 + 语言设置）。</td></tr><tr><td><strong>交换文件…</strong></td><td>传递 <code>.mntpl</code> 版式模板、<code>.mnexp</code> 导出模板，或单个 <code>.mnpage.json</code> 页面。</td></tr><tr><td><strong>备份 / 恢复</strong></td><td>把 <code>data/</code> 打包成 ZIP，或恢复之前的 ZIP。</td></tr></tbody></table><p>导入会先校验，原文件会备份到 <code>data/backups/</code>。文件内容和版本规则见<a href="/KomaYomi-docs/zh/guide/project-files">工程文件与格式</a>。</p><div class="tip custom-block"><p class="custom-block-title">导入顺序</p><p>想把标注恢复到同一台机器上，用<strong>备份</strong>恢复。换到另一台机器时导入<strong>工程</strong>。只想分享一个版式、一种导出样式或一页时，用<strong>交换文件</strong>。</p></div><h2 id="导航与性能" tabindex="-1">导航与性能 <a class="header-anchor" href="#导航与性能" aria-label="Permalink to &quot;导航与性能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>快捷键</th></tr></thead><tbody><tr><td>上一页 / 下一页</td><td><code>[</code> / <code>]</code></td></tr><tr><td>切格工作台</td><td><code>P</code></td></tr><tr><td>对照阅读</td><td><code>C</code></td></tr><tr><td>显示 / 隐藏侧栏</td><td><code>S</code></td></tr><tr><td>显示 / 隐藏笔记栏</td><td><code>N</code></td></tr><tr><td>打开导出对话框</td><td><code>E</code></td></tr><tr><td>帮助</td><td><code>?</code></td></tr></tbody></table><p>URL hash 可以深链接：<code>#/&lt;volume&gt;/&lt;chapter&gt;/&lt;page&gt;/&lt;panels|compare&gt;</code>。</p><p>缩略图按需生成，缓存在 <code>data/cache/thumbs/</code>。删除该目录是安全的，下次访问时会重新生成。图片格式从文件头判断，因此扩展名为 <code>.png</code> 但实际是 JPEG 的文件仍能正确显示。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>重命名文件会改变它的页位置。</strong> 配对按排序索引进行；在中间插入一页会把其后所有页后移。把新页加在末尾，或整话统一重命名。见<a href="/KomaYomi-docs/zh/guide/preprocess">预处理与重命名</a>。</li><li><strong>缺一种语言不是错误。</strong> 页面仍可打开，对照阅读会为缺失的语言显示占位。</li><li><strong>目录链接不是副本。</strong> 移动或删除原文件夹后，图库会失效。移动后请重新添加该文件夹。</li><li><strong>WebP 可以显示，但不会解码用于检测。</strong> 依赖自动切格时请使用 JPEG 或 PNG（见<a href="/KomaYomi-docs/zh/guide/panels">切格工作台</a>）。</li><li><strong>以侧栏为准。</strong> 如果某一卷或某一话没有出现，先检查文件夹名大小写和语言别名。</li><li><strong>语言下拉框里找不到某个文件夹。</strong> 它已经在卷设置里分配给了另一种语言。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/guide/preprocess">预处理与重命名</a> —— 导入前把扫描件整理干净。</li><li><a href="/KomaYomi-docs/zh/guide/folder-rules">目录识别规则</a> —— 非标准目录结构。</li><li><a href="/KomaYomi-docs/zh/guide/panels">切格工作台</a> —— 页面打开之后要做什么。</li><li><a href="/KomaYomi-docs/zh/guide/project-files">工程文件与格式</a> —— <code>.mnproj</code> 里有什么。</li><li><a href="/KomaYomi-docs/zh/guide/remote">远端存储与备份</a> —— 把图片放在 NAS 或 WebDAV 上。</li></ul>',50)])])}const E=d(r,[["render",i]]);export{k as __pageData,E as default};
